/** Resolves a slug, alias, or loose label ("Spring Boot", "K8s") to a mark. */
export function lookupTechIcon(name?: string | null): TechIconDef | null {
  if (!name) return null;
  const k = String(name).trim().toLowerCase().replace(/[\s_.]+/g, '-');
  if (TECH_ICONS[k]) return TECH_ICONS[k];
  if (TECH_ALIASES[k]) return TECH_ICONS[TECH_ALIASES[k]] ?? null;
  const bare = k.replace(/-/g, '');
  for (const def of Object.values(TECH_ICONS)) {
    if (def.slug.replace(/-/g, '') === bare) return def;
  }
  return null;
}
